-- Neo Metaliks NMS Complete Database Schema and Initial Seed Data
CREATE DATABASE IF NOT EXISTS `neo_metaliks_nms` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `neo_metaliks_nms`;

DROP TABLE IF EXISTS `admins`;
CREATE TABLE `admins` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `email` varchar(150) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `department` varchar(100) DEFAULT NULL,
  `location` varchar(150) DEFAULT NULL,
  `profile_image` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devices`;
CREATE TABLE `devices` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `device_code` varchar(50) NOT NULL,
  `device_name` varchar(100) NOT NULL,
  `device_type` varchar(50) NOT NULL,
  `ip_address` varchar(45) NOT NULL,
  `mac_address` varchar(17) DEFAULT NULL,
  `location` varchar(150) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'Unknown',
  `monitoring_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `monitoring_interval` int(10) unsigned NOT NULL DEFAULT 30,
  `last_check` datetime DEFAULT NULL,
  `last_latency_ms` decimal(10,2) DEFAULT NULL,
  `uptime_percent` decimal(5,2) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `total_checks` int(11) NOT NULL DEFAULT 0,
  `successful_checks` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_device_code` (`device_code`),
  KEY `idx_device_type` (`device_type`),
  KEY `idx_device_status` (`status`),
  KEY `idx_ip_address` (`ip_address`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `cameras`;
CREATE TABLE `cameras` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `camera_code` varchar(50) NOT NULL,
  `camera_name` varchar(150) NOT NULL,
  `ip_address` varchar(45) NOT NULL,
  `location` varchar(150) DEFAULT NULL,
  `status` varchar(20) DEFAULT 'Unknown',
  `monitoring_enabled` tinyint(1) DEFAULT 1,
  `monitoring_interval` int(11) DEFAULT 1800,
  `offline_retry_interval` int(11) DEFAULT 120,
  `last_check` datetime DEFAULT NULL,
  `last_latency_ms` decimal(10,2) DEFAULT NULL,
  `total_checks` int(11) DEFAULT 0,
  `successful_checks` int(11) DEFAULT 0,
  `uptime_percent` decimal(6,2) DEFAULT 0.00,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `camera_code` (`camera_code`),
  UNIQUE KEY `ip_address` (`ip_address`)
) ENGINE=InnoDB AUTO_INCREMENT=64 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `desktops`;
CREATE TABLE `desktops` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `desktop_code` varchar(100) NOT NULL,
  `department` varchar(100) DEFAULT NULL,
  `location` varchar(150) DEFAULT NULL,
  `ip_address` varchar(45) NOT NULL,
  `operating_system` varchar(100) DEFAULT NULL,
  `cpu_usage` decimal(5,2) DEFAULT 0.00,
  `ram_usage` decimal(5,2) DEFAULT 0.00,
  `status` varchar(20) DEFAULT 'Unknown',
  `monitoring_enabled` tinyint(1) DEFAULT 1,
  `monitoring_interval` int(11) DEFAULT 30,
  `last_check` datetime DEFAULT NULL,
  `last_latency_ms` decimal(10,2) DEFAULT NULL,
  `total_checks` int(11) DEFAULT 0,
  `successful_checks` int(11) DEFAULT 0,
  `uptime_percent` decimal(5,2) DEFAULT 0.00,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `desktop_code` (`desktop_code`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `desktop_monitoring_settings`;
CREATE TABLE `desktop_monitoring_settings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `enabled` tinyint(1) DEFAULT 0,
  `selected_location` varchar(150) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `alerts`;
CREATE TABLE `alerts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `source_type` varchar(50) DEFAULT NULL,
  `source_name` varchar(100) DEFAULT NULL,
  `message` text DEFAULT NULL,
  `severity` varchar(20) DEFAULT NULL,
  `status` varchar(20) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=684 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `logs`;
CREATE TABLE `logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `event_type` varchar(50) DEFAULT NULL,
  `source_name` varchar(100) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

